L["Legion Commander Yorik"] = "Legionskommandant Yorik"
L["Legion: The Legion Returns"] = "Legion: Die Rückkehr der Legion"
L["Lending a Hand"] = "Eine helfende Hand"
L["Let Sleeping Wolves Lie"] = "Schlafende Wölfe soll man nicht wecken"
